select
con.Con_Name as conName, con.Con_Code as conCode, c1.C_Name as ptContractorName, c1.C_Abbreviation as ptContractorAbbName, c2.C_Name as ptSupervisorName, c2.C_Abbreviation as ptSupervisorAbbName, c3.C_Name as ptEvaluationUnitName, c3.C_Abbreviation as ptEvaluationUnitAbbName, c4.C_Name as ptRectifyName, c4.C_Abbreviation as ptRectifyAbbName, u1.U_Name as ptPmName, u2.U_Name as ptCseName, qp.Qsp_Code as qspCode, qp.Qsp_Name as qspName, (select count(*) from Qs_Record rec where rec.Pt_Id=mn.id and rec.Qsr_State!=3) as qsRecordCount, (select count(*) from Qs_Record rec where rec.Pt_Id=mn.id and rec.Qsr_State!=3 and rec.Qsr_Rectify_Status='03') as qsFinishCount, (select count(*) from Qs_Record rec where rec.Pt_Id=mn.id and rec.Qsr_State!=3 and rec.Qsr_Rectify_Reply is not null) as qsReplyCount, mn.* from Qs_Plan_Task mn left join Qs_Plan qp on qp.Qsp_Id=mn.Qsp_Id
left join Con_Contract con on con.Con_Id = mn.Con_Id left join SYS_Company c1 on c1.C_Id = mn.Pt_Contractor_Id left join SYS_Company c2 on c2.C_Id = mn.Pt_Supervisor_Id left join SYS_Company c3 on c3.C_Id = mn.Pt_Evaluation_Unit_Id left join SYS_Company c4 on c4.C_Id = mn.Pt_Rectify_Cid left join Sys_User u1 on u1.U_Id = mn.Pt_Pm left join Sys_User u2 on u2.U_Id = mn.Pt_Cse
${params.authSql}
where 1=1
and mn.Te_Id = #{params.teId}
and mn.Pt_Type=#{params.ptType}
and mn.Pt_Category=#{params.ptCategory}
and mn.State=#{params.state}
and mn.P_Id=#{params.pId}
and mn.Pt_Measure=#{params.ptMeasure}
and mn.Pt_Is_Construction=#{params.ptIsConstruction}
and INSTR(mn.Create_Uname,#{params.createUname})
and INSTR(mn.Pt_Code,#{params.ptCode})
and INSTR(mn.Pt_Group_Leader_Name,#{params.ptGroupLeaderName})
and INSTR(mn.Pt_Team_Leader_Name,#{params.ptTeamLeaderName})
and INSTR(mn.Pt_Group_Member_Name,#{params.ptGroupMemberName})
and likePname(#{params.pName},pro.P_Id)=true
and INSTR(pro.P_Name,#{params.pName})
and INSTR(con.Con_Name,#{params.conName})
and INSTR(u1.U_Name,#{params.ptPmName})
and INSTR(u2.U_Name,#{params.ptCseName})
and likeCname(#{params.ptContractorName},c1.C_Id)=true
and INSTR(c1.C_Name,#{params.ptContractorName})
and likeCname(#{params.ptSupervisorName},c2.C_Id)=true
and INSTR(c2.C_Name,#{params.ptSupervisorName})
and likeCname(#{params.ptRectifyName},c4.C_Id)=true
and INSTR(c4.C_Name,#{params.ptRectifyName})
and to_char(mn.Pt_Evaluation_Time,'yyyy-MM-dd') >= #{params.ptEvaluationTimeStart}
and to_char(mn.Pt_Evaluation_Time,'yyyy-MM-dd') <= #{params.ptEvaluationTimeEnd}
and (select count(*) from Qs_Record rec where rec.Pt_Id=mn.id and TO_CHAR(rec.Qsr_Rectify_Require_Time,'yyyy-mm-dd') > TO_CHAR(now(),'yyyy-mm-dd') and rec.Qsr_Rectify_Status!='03' ) = (select count(*) from Qs_Record rec where rec.Pt_Id=mn.id )
and (select count(*) from Qs_Record rec where rec.Pt_Id=mn.id and TO_CHAR(rec.Qsr_Rectify_Require_Time,'yyyy-mm-dd') < TO_CHAR(now(),'yyyy-mm-dd') and rec.Qsr_Rectify_Status!='03' ) >0
and mn.Pt_Cid=#{params.ptCid}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time DESC

