SELECT
SUM((SELECT COUNT(*) FROM Qs_Record rec WHERE rec.Pt_Id = mn.id AND rec.Qsr_State != 3)) AS totalQsRecordCount,
SUM((SELECT COUNT(*) FROM Qs_Record rec WHERE rec.Pt_Id = mn.id AND rec.Qsr_State != 3 AND rec.Qsr_Rectify_Status = '03')) AS totalQsFinishCount,
SUM((SELECT COUNT(*) FROM Qs_Record rec WHERE rec.Pt_Id = mn.id AND rec.Qsr_State != 3 AND rec.Qsr_Rectify_Reply IS NOT NULL)) AS totalQsReplyCount
from Qs_Plan_Task mn
left join Qs_Plan qp on qp.Qsp_Id=mn.Qsp_Id

left join Con_Contract con on con.Con_Id = mn.Con_Id
left join SYS_Company c1 on c1.C_Id = mn.Pt_Contractor_Id
left join SYS_Company c2 on c2.C_Id = mn.Pt_Supervisor_Id
left join SYS_Company c3 on c3.C_Id = mn.Pt_Evaluation_Unit_Id
left join SYS_Company c4 on c4.C_Id = mn.Pt_Rectify_Cid
left join Sys_User u1 on u1.U_Id = mn.Pt_Pm
left join Sys_User u2 on u2.U_Id = mn.Pt_Cse

