select * from ( select qr.Qsr_Id qsrId,qr.Qst_Id qstId,qt.Qst_Name qstName,qt.Qst_Code qstCode,mn.P_Id pId,pro.P_Name projectName, qr.Qsr_Des qsrDes,mn.Pt_Type ptType,mn.Pt_Evaluation_Time ptEvaluationTime,mn.Pt_Group_Member ptGroupMember, mn.Pt_Group_Member_Name, ROW_NUMBER() over(partition by qr.Qst_Id order by qr.Qst_Id desc) as rn, COUNT(*) OVER (PARTITION BY mn.P_Id, qr.Qst_Id) AS recordCount, pro.* from Qs_Record qr left join Qs_Plan_Task mn on mn.id=qr.pt_id left join QS_Type qt on qt.Qst_Id=qr.Qst_Id left join Pre_Project pro ON pro.P_Id = mn.P_Id
${params.authSql}
where 1=1
and mn.State!=3 and qr.Qst_Id is not null
)t where rn=1 order by recordCount desc

SELECT MIN(qr.Qsr_Id) AS qsrId, COUNT(qr.Qst_Id) AS recordCount, qr.Qst_Id AS qstId, MIN(qt.Qst_Name) AS qstName, MIN(qt.Qst_Code) AS qstCode, MIN(mn.pt_Code) AS ptCode, MIN(mn.P_Id) AS pId, MIN(pro.P_Name) AS pName, MIN(qr.Qsr_Des) AS qsrDes, MIN(mn.Pt_Type) AS ptType, MIN(mn.Pt_Evaluation_Time) AS ptEvaluationTime, MIN(mn.Pt_Group_Member) AS ptGroupMember, MIN(mn.Pt_Group_Member_Name) AS ptGroupMemberName FROM Qs_Record qr LEFT JOIN Qs_Plan_Task mn ON mn.id = qr.pt_id LEFT JOIN QS_Type qt ON qt.Qst_Id = qr.Qst_Id LEFT JOIN Pre_Project pro ON pro.P_Id = mn.P_Id
${params.authSql}
where 1=1
and mn.State != 3 and mn.State != 0 AND qr.Qst_Id IS NOT NULL
GROUP BY mn.P_Id,qr.Qst_Id order by count(qr.Qst_Id) desc ;

select con.Con_Name as conName, pro.P_Name as pName, con.Con_Code as conCode, con.Con_Money_Total as conMoneyTotal, proc.C_Name as pConstructionUnitName, proc.C_Abbreviation as pConsAbbName, prod.D_Name as pCompetentDepartmentName, qt.Qst_Name as qstName, qt.Qst_Code as qstCode, qt.Qst_Item as qstItem, qt.Qst_Is_Important as qstIsImportant, c1.C_Name as qsrDutyCpyName, u1.U_Name as rectifyUname, mn.* from Qs_Record mn left join Qs_Type qt on qt.Qst_Id = mn.Qst_Id left join Con_Contract con on con.Con_Id = mn.Con_Id left join Pre_Project pro on pro.P_Id = mn.P_Id left join SYS_Company proc on proc.C_Id = pro.P_Construction_Unit left join SYS_Department prod on prod.D_Id = pro.P_Competent_Department left join SYS_Company c1 on c1.C_Id = mn.Qsr_Duty_Cpy left join Sys_User u1 on u1.U_Id = mn.Qsr_Rectify_Uid where mn.Pt_Id = #{id}
and qt.qst_path like concat(#{qsTypeId},'%')
order by mn.Qsr_Create_Time ASC

select pro.P_Name as pName, pro.P_Code as pCode, con.Con_Name as conName, con.Con_Code as conCode, c1.C_Name as ptContractorName, c1.C_Abbreviation as ptContractorAbbName, c2.C_Name as ptSupervisorName, c2.C_Abbreviation as ptSupervisorAbbName, c3.C_Name as ptEvaluationUnitName, c3.C_Abbreviation as ptEvaluationUnitAbbName, c4.C_Name as ptRectifyName, c4.C_Abbreviation as ptRectifyAbbName, u1.U_Name as ptPmName, u2.U_Name as ptCseName, qp.Qsp_Code as qspCode, qp.Qsp_Name as qspName, mn.* from Qs_Plan_Task mn left join Qs_Plan qp on qp.Qsp_Id = mn.Qsp_Id left join Pre_Project pro on pro.P_Id = mn.P_Id left join Con_Contract con on con.Con_Id = mn.Con_Id left join SYS_Company c1 on c1.C_Id = mn.Pt_Contractor_Id left join SYS_Company c2 on c2.C_Id = mn.Pt_Supervisor_Id left join SYS_Company c3 on c3.C_Id = mn.Pt_Evaluation_Unit_Id left join SYS_Company c4 on c4.C_Id = mn.Pt_Rectify_Cid left join Sys_User u1 on u1.U_Id = mn.Pt_Pm left join Sys_User u2 on u2.U_Id = mn.Pt_Cse
