select pro.P_Name as pName, pro.P_id as pId, cc.con_id as conId, cc.con_name as conName, proc.C_Name as pConstructionUnitName, proc.C_Abbreviation as pConsAbbName, prod.D_Name as pCompetentDepartmentName, f.file_relation_id as fileRelationId, qt.Qst_Name as qstName, qt.Qst_Code as qstCode, qt.Qst_Item as qstItem, qt.Qst_Is_Important as qstIsImportant, c1.C_Name as qsrDutyCpyName, u1.U_Name as rectifyUname, qt.Qst_Is_Important as qstIsImportant, qt.qst_path as qstPath, mn.pt_code as ptCode, qr.*,mn.Create_Time as createTime from Qs_Record qr left join Qs_Plan_Task mn on mn.id=qr.pt_id left join QS_Type qt on qt.Qst_Id=qr.Qst_Id left join Pre_Project pro ON pro.P_Id = mn.P_Id left join SYS_Company proc on proc.C_Id = pro.P_Construction_Unit left join SYS_Department prod on prod.D_Id = pro.P_Competent_Department left join SYS_Company c1 on c1.C_Id = qr.Qsr_Duty_Cpy left join Sys_User u1 on u1.U_Id = qr.Qsr_Rectify_Uid left join Sys_File f on f.FileID = qr.Qsr_Id left join con_contract cc on cc.con_id = mn.con_id
mn.State!=3
